// Architectural images from the 3D model, generated by Cloudinary. The app uploads a snapshot of the model (PNG with a
// transparent background); we upload it to Cloudinary with a signed request and ask for the chosen image as an
// eager (pre-generated) transformation, so delivery URLs work even with "strict transformations" on.
// Config: CLOUDINARY_CLOUD_NAME and CLOUDINARY_API_KEY (vars), CLOUDINARY_API_SECRET (secret).
import { Hono } from 'hono';
import { VISUAL_STYLES, cleanPrompt } from '../../shared/visual-styles';
import { projectAccess } from './access';
import { type AppEnv, type Env, fail, now, uid } from './util';

export const visualsOn = (env: Env) => !!(env.CLOUDINARY_CLOUD_NAME && env.CLOUDINARY_API_KEY && env.CLOUDINARY_API_SECRET);
const DAILY = 20; // generated images per user per day (generative transformations cost Cloudinary credits)
const MAX_BYTES = 8 * 1024 * 1024;

const enc = (s: string) => encodeURIComponent(s); // spaces, commas and slashes must not break the transformation
/** The eager transformation for a style: generative scene behind the model, then delivery settings. */
export function transformationFor(style: string, prompt: string | null): string {
  const out = 'c_limit,w_1600/f_jpg,q_auto';
  switch (style) {
    case 'wide': return `e_gen_background_replace:prompt_${enc(prompt!)}/c_pad,ar_16:9,b_gen_fill,w_1600/f_jpg,q_auto`;
    case 'board': return `b_rgb:f4f1ea,c_pad,ar_4:3,w_1600/e_sharpen:60/f_jpg,q_auto`;
    default: return `e_gen_background_replace:prompt_${enc(prompt!)}/${out}`;
  }
}

const hex = (buf: ArrayBuffer) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
/** Cloudinary request signature: parameters sorted by name, joined as k=v&..., the API secret appended, SHA-1. */
export async function signParams(params: Record<string, string>, secret: string) {
  const s = Object.keys(params).sort().map((k) => `${k}=${params[k]}`).join('&');
  return hex(await crypto.subtle.digest('SHA-1', new TextEncoder().encode(s + secret)));
}

type Row = { id: string; public_id: string; format: string; style: string; prompt: string | null; transformation: string; created_at: number; user_email: string | null };
const urls = (env: Env, r: Row) => {
  const base = `https://res.cloudinary.com/${env.CLOUDINARY_CLOUD_NAME}/image/upload`;
  return { image: `${base}/${r.transformation}/${r.public_id}.jpg`, source: `${base}/${r.public_id}.${r.format}` };
};
const out = (env: Env, { transformation: _t, public_id: _p, format: _f, ...r }: Row) => ({ ...r, ...urls(env, { ...r, transformation: _t, public_id: _p, format: _f }) });

export const visuals = new Hono<AppEnv>();

visuals.get('/', async (c) => {
  const project = await projectAccess(c, c.req.param('id')!);
  if (!visualsOn(c.env)) return c.json({ enabled: false, styles: VISUAL_STYLES, visuals: [] });
  const { results } = await c.env.DB.prepare(`SELECT v.id, v.public_id, v.format, v.style, v.prompt, v.transformation, v.created_at, u.email AS user_email
    FROM visuals v LEFT JOIN users u ON u.id = v.user_id WHERE v.project_id = ? ORDER BY v.created_at DESC LIMIT 60`).bind(project.id).all<Row>();
  return c.json({ enabled: true, styles: VISUAL_STYLES, visuals: results.map((r) => out(c.env, r)) });
});

/** Body: the PNG snapshot. Headers: x-style (a preset key or 'custom'), x-prompt (URL-encoded, for 'custom'). */
visuals.post('/', async (c) => {
  const project = await projectAccess(c, c.req.param('id')!);
  if (!visualsOn(c.env)) throw fail(503, 'Image generation is not set up on this server.');
  const user = c.get('user');
  const style = c.req.header('x-style') ?? '';
  const preset = VISUAL_STYLES.find((s) => s.key === style);
  const custom = style === 'custom' ? cleanPrompt(decodeURIComponent(c.req.header('x-prompt') ?? '')) : '';
  if (!preset && !(style === 'custom' && custom.length >= 3)) throw fail(400, style === 'custom' ? 'Describe the scene in a few words.' : 'Unknown style.');
  if (!/^image\/png$/.test(c.req.header('content-type') ?? '')) throw fail(415, 'Send the model snapshot as a PNG.');
  const body = await c.req.arrayBuffer();
  if (!body.byteLength) throw fail(400, 'The snapshot is empty.');
  if (body.byteLength > MAX_BYTES) throw fail(413, 'The snapshot is larger than 8 MB.');
  const today = await c.env.DB.prepare('SELECT COUNT(*) AS n FROM visuals WHERE user_id = ? AND created_at > ?').bind(user.id, now() - 86400000).first<{ n: number }>();
  if ((today?.n ?? 0) >= DAILY) throw fail(429, `You've generated ${DAILY} images in the last 24 hours. Try again tomorrow.`);

  const prompt = preset ? preset.prompt : custom;
  const transformation = transformationFor(preset ? preset.key : 'custom', prompt);
  const params: Record<string, string> = {
    eager: transformation, eager_async: 'true', folder: `bimp/${project.id}`, tags: 'bimp,model-snapshot', timestamp: String(Math.floor(now() / 1000)),
  };
  const form = new FormData();
  form.set('file', new Blob([body], { type: 'image/png' }), 'model.png');
  for (const [k, v] of Object.entries(params)) form.set(k, v);
  form.set('api_key', c.env.CLOUDINARY_API_KEY!);
  form.set('signature', await signParams(params, c.env.CLOUDINARY_API_SECRET!));
  const res = await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(c.env.CLOUDINARY_CLOUD_NAME!)}/image/upload`, { method: 'POST', body: form });
  const d = (await res.json().catch(() => ({}))) as { public_id?: string; format?: string; error?: { message?: string } };
  if (!res.ok || !d.public_id) throw fail(502, `Cloudinary refused the upload: ${d.error?.message ?? res.status}`);

  const row: Row = { id: uid(), public_id: d.public_id, format: d.format ?? 'png', style: preset ? preset.key : 'custom', prompt, transformation, created_at: now(), user_email: user.email };
  await c.env.DB.prepare('INSERT INTO visuals (id, project_id, user_id, public_id, format, style, prompt, transformation, created_at) VALUES (?,?,?,?,?,?,?,?,?)')
    .bind(row.id, project.id, user.id, row.public_id, row.format, row.style, row.prompt, row.transformation, row.created_at).run();
  return c.json({ visual: out(c.env, row) });
});

visuals.delete('/:vid', async (c) => {
  const project = await projectAccess(c, c.req.param('id')!);
  const r = await c.env.DB.prepare('DELETE FROM visuals WHERE id = ? AND project_id = ?').bind(c.req.param('vid'), project.id).run();
  if (!r.meta.changes) throw fail(404, 'Image not found.');
  return c.json({ ok: true });
});
